import re
import sys
from datetime import date, timedelta
from pathlib import Path

LOG_DIR = Path("/app/logs")
OUT_PATH = Path("/app/summary.csv")
TODAY = date(2025, 8, 12)

SEVERITIES = ["ERROR", "WARNING", "INFO"]
FNAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")
SEV_RE = re.compile(r"\[(ERROR|WARNING|INFO)\]")

last_7_start = TODAY - timedelta(days=6)
last_30_start = TODAY - timedelta(days=29)
month_start = TODAY.replace(day=1)

periods = {
    "today": lambda d: d == TODAY,
    "last_7_days": lambda d: last_7_start <= d <= TODAY,
    "last_30_days": lambda d: last_30_start <= d <= TODAY,
    "month_to_date": lambda d: month_start <= d <= TODAY,
    "total": lambda d: True,
}

counts = {p: {s: 0 for s in SEVERITIES} for p in periods}

for f in sorted(LOG_DIR.iterdir()):
    m = FNAME_RE.match(f.name)
    if not m:
        continue
    file_date = date.fromisoformat(m.group(1))
    sev_counts = {s: 0 for s in SEVERITIES}
    with f.open(encoding="utf-8", errors="replace") as fh:
        for line in fh:
            sm = SEV_RE.search(line)
            if sm:
                sev_counts[sm.group(1)] += 1

    for pname, pred in periods.items():
        if pred(file_date):
            for s in SEVERITIES:
                counts[pname][s] += sev_counts[s]

with OUT_PATH.open("w", encoding="utf-8") as out:
    out.write("period,severity,count\n")
    for pname in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for s in SEVERITIES:
            out.write(f"{pname},{s},{counts[pname][s]}\n")

print(OUT_PATH.read_text())

